INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Standarddatum immer mit dem Tag beginnt?', 2, '[{"text": "No", "correct": true, "because": "Year comes first in the standard"}, {"text": "Yes", "correct": false, "because": "Format is YYYY-MM-DD"}]'),
('00000000-0000-0000-0000-000000000000', 'Which format correctly represents a date in this standard?', 3, '[{"text": "2025-04-11", "correct": true, "because": "Follows YYYY-MM-DD"}, {"text": "04-11-2025", "correct": false, "because": "Wrong order"}, {"text": "11/04/2025", "correct": false, "because": "Uses slashes"}]'),
('00000000-0000-0000-0000-000000000000', 'What elements are included in this time standard?', 5, '[{"text": "Year", "correct": true, "because": "Part of date"}, {"text": "Month", "correct": true, "because": "Essential component"}, {"text": "Day", "correct": true, "because": "Completes date"}, {"text": "Color coding", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) It uses YYYY-MM-DD. b) Time is written as DD:HH:MM.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Time is HH:MM:SS"}, {"text": "Both are correct", "correct": false, "because": "b) is wrong"}, {"text": "Only b) is correct", "correct": false, "because": "a) is correct"}, {"text": "Both are incorrect", "correct": false, "because": "a) is right"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I overlook when setting up a timestamp?', 4, '[{"text": "Time zone", "correct": false, "because": "Can be included"}, {"text": "Date order", "correct": false, "because": "Critical for standard"}, {"text": "Office decoration", "correct": true, "because": "Not a technical factor"}]'),
('00000000-0000-0000-0000-000000000000', 'I heard that this standard only works for dates, not times. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Covers date and time"}, {"text": "Yes", "correct": false, "because": "Includes time too"}]'),
('00000000-0000-0000-0000-000000000000', 'Which example correctly includes time in this format?', 3, '[{"text": "2025-04-11T14:30:00", "correct": true, "because": "Uses T separator"}, {"text": "2025-04-11 14:30", "correct": false, "because": "Missing T"}, {"text": "14:30 2025-04-11", "correct": false, "because": "Wrong order"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does this date standard offer?', 5, '[{"text": "Consistency", "correct": true, "because": "Unified format"}, {"text": "Sortability", "correct": true, "because": "Year-first ordering"}, {"text": "Interoperability", "correct": true, "because": "Global standard"}, {"text": "Color coding", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'I heard that a) 2025-04-11 is correct and b) it always uses slashes. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Uses hyphens, not slashes"}, {"text": "Both are correct", "correct": false, "because": "b) is wrong"}, {"text": "Only b) is correct", "correct": false, "because": "a) is correct"}, {"text": "Both are incorrect", "correct": false, "because": "a) is right"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need to use this time format?', 4, '[{"text": "Date components", "correct": false, "because": "Essential parts"}, {"text": "Time separator", "correct": false, "because": "T is required"}, {"text": "Office decoration", "correct": true, "because": "Not a technical factor"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does this standard support time zones?', 2, '[{"text": "Yes", "correct": true, "because": "Z or offset allowed"}, {"text": "No", "correct": false, "because": "Includes time zones"}]'),
('00000000-0000-0000-0000-000000000000', 'Which parts of this standard handle time zones?', 4, '[{"text": "Z for UTC", "correct": true, "because": "Indicates Zulu time"}, {"text": "+01:00 offset", "correct": true, "because": "Shows time difference"}, {"text": "MM-DD offset", "correct": false, "because": "Not a format"}]'),
('00000000-0000-0000-0000-000000000000', 'I heard that this format is only for databases. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Used in files, APIs too"}, {"text": "Yes", "correct": false, "because": "Widely applicable"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s the goal of using a standard date format?', 3, '[{"text": "Uniformity", "correct": true, "because": "Consistent representation"}, {"text": "Data compression", "correct": false, "because": "Different purpose"}, {"text": "Design improvement", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) It uses 24-hour time. b) Day comes before month.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Month before day"}, {"text": "Both are correct", "correct": false, "because": "b) is wrong"}, {"text": "Only b) is correct", "correct": false, "because": "a) is correct"}, {"text": "Both are incorrect", "correct": false, "because": "a) is right"}]'),
('00000000-0000-0000-0000-000000000000', 'What role does the “T” play in this format?', 4, '[{"text": "Separates date and time", "correct": true, "because": "Marks transition"}, {"text": "Indicates time zone", "correct": false, "because": "Z or offset does that"}, {"text": "Color codes", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if this standard allows fractional seconds?', 2, '[{"text": "Yes", "correct": true, "because": "E.g., .123 allowed"}, {"text": "No", "correct": false, "because": "Supports precision"}]'),
('00000000-0000-0000-0000-000000000000', 'What makes this date standard useful in IT?', 5, '[{"text": "Global acceptance", "correct": true, "because": "Standardized"}, {"text": "Easy sorting", "correct": true, "because": "Year-first"}, {"text": "Precision", "correct": true, "because": "Includes time"}, {"text": "Visual appeal", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Is 11-04-2025 a valid format here?', 3, '[{"text": "No", "correct": true, "because": "Should be 2025-04-11"}, {"text": "Yes", "correct": false, "because": "Wrong order"}]'),
('00000000-0000-0000-0000-000000000000', 'Which scenario fits this time standard?', 4, '[{"text": "Logging 2025-04-11T14:30:00Z", "correct": true, "because": "Typical use"}, {"text": "Displaying 04/11/2025", "correct": false, "because": "Non-standard"}, {"text": "Compressing data", "correct": false, "because": "Different purpose"}]');
